package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                       // PIC X len=1 = "N"
var WsLabel string = strings.Repeat(" ", 20)     // PIC X(20) len=20 = SPACES
var WsACount int64 = 0                           // PIC 99 len=2 = 0
var WsTotalA int64 = 0                           // PIC 999 len=3 = 0
var WsCount int64 = 0                            // PIC 999 len=3 = 0

var PartRecData PartRec
var partFile *os.File
var partReader *bufio.Reader

func InputDone() bool {
	return WsEofFlag == "Y"
}

func readNextLine() (string, bool) {
	s, err := partReader.ReadString('\n')
	if err != nil {
		if err == io.EOF {
			if len(s) == 0 {
				return "", false
			}
			line := s
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
			return line, true
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
		return "", false
	}
	line := s[:len(s)-1]
	if len(line) > 0 && line[len(line)-1] == '\r' {
		line = line[:len(line)-1]
	}
	return line, true
}

func padTo15(s string) string {
	if len(s) >= 15 {
		return s[:15]
	}
	return s + strings.Repeat(" ", 15-len(s))
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	partFile = f
	partReader = bufio.NewReader(f)
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	f.Close()
	SummaryPara()
}

func ReadPara() {
	line, ok := readNextLine()
	if !ok {
		WsEofFlag = "Y"
		return
	}
	rec := padTo15(line)
	lbPart := rec[0:8]
	lbRegion := rec[8:11]
	lbSerialStr := rec[11:15]
	var serial int64 = 0
	trimmed := strings.TrimSpace(lbSerialStr)
	if trimmed != "" {
		v, err := strconv.ParseInt(trimmed, 10, 64)
		if err != nil {
			serial = 0
		} else {
			serial = ((v % 10000) + 10000) % 10000
		}
	} else {
		serial = 0
	}
	PartRecData.LbPart = lbPart
	PartRecData.LbRegion = lbRegion
	PartRecData.LbSerial = serial
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	cnt := int64(strings.Count(PartRecData.LbPart, "A"))
	WsACount = WsACount + cnt
	WsACount = WsACount % 100
	sRegion := PartRecData.LbRegion
	if idx := strings.Index(sRegion, " "); idx >= 0 {
		sRegion = sRegion[:idx]
	}
	sPart := PartRecData.LbPart
	if idx := strings.Index(sPart, " "); idx >= 0 {
		sPart = sPart[:idx]
	}
	sv := PartRecData.LbSerial % 10000
	if sv < 0 {
		sv += 10000
	}
	sSerial := fmt.Sprintf("%04d", sv)
	concat := sRegion + "-" + sPart + "-" + sSerial
	if len(concat) >= 20 {
		WsLabel = concat[:20]
	} else {
		WsLabel = concat + strings.Repeat(" ", 20-len(concat))
	}
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	WsTotalA = WsTotalA + WsACount
	WsTotalA = WsTotalA % 1000
	WsCount = WsCount + 1
	WsCount = WsCount % 1000
	aStr := fmt.Sprintf("%02d", WsACount)
	fmt.Printf("%s%s%s\n", WsLabel, " A=", aStr)
	ReadPara()
}

func SummaryPara() {
	cStr := fmt.Sprintf("%03d", WsCount)
	tStr := fmt.Sprintf("%03d", WsTotalA)
	fmt.Printf("%s%s%s%s\n", "LABELS: ", cStr, " A-TOTAL: ", tStr)
}

func main() {
	MainPara()
}
